begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('e1000000-0000-4000-8000-000000000001','ezyvet-admin@example.test','{"first_name":"Synthetic","last_name":"Admin"}'),
 ('e1000000-0000-4000-8000-000000000002','ezyvet-staff@example.test','{"first_name":"Synthetic","last_name":"Staff"}'),
 ('e1000000-0000-4000-8000-000000000003','ezyvet-inactive@example.test','{"first_name":"Synthetic","last_name":"Inactive"}');
update public.profiles set is_active = true where id in ('e1000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000002','e1000000-0000-4000-8000-000000000003');
insert into public.user_roles (user_id, role) values ('e1000000-0000-4000-8000-000000000001','STAFF'),('e1000000-0000-4000-8000-000000000002','STAFF'),('e1000000-0000-4000-8000-000000000003','STAFF');

insert into public.user_roles(user_id,role) values ('e1000000-0000-4000-8000-000000000001','ADMIN'),('e1000000-0000-4000-8000-000000000003','ADMIN');
update public.profiles set is_active=false where id='e1000000-0000-4000-8000-000000000003';
create temp table original_counts as select (select count(*) from public.clients) clients,(select count(*) from public.pets) pets,(select count(*) from public.clinical_encounters) encounters;
select ok(not has_table_privilege('authenticated','public.ezyvet_import_snapshots','INSERT'),'Authenticated clients cannot directly inject snapshots');
select ok(not has_table_privilege('service_role','public.ezyvet_import_snapshots','UPDATE'),'Service API cannot overwrite immutable snapshots');
select ok(not has_table_privilege('authenticated','public.ezyvet_import_reviews','DELETE'),'Review history cannot be deleted');
select ok(not has_table_privilege('anon','public.ezyvet_import_snapshots','SELECT'),'Anonymous cannot read imports');
select ok(not has_function_privilege('authenticated','public.claim_ezyvet_import(uuid,uuid,text,text,text)','EXECUTE'),'Browser cannot run privileged import claim');
set local role service_role;
select throws_ok($$select public.claim_ezyvet_import('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000002','synthetic-site','contact','https://api.trial.ezyvet.com')$$,'42501','Active administrator required','Staff import denied');
select throws_ok($$select public.claim_ezyvet_import('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000003','synthetic-site','contact','https://api.trial.ezyvet.com')$$,'42501','Active administrator required','Inactive administrator import denied');
select lives_ok($$select public.claim_ezyvet_import('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','synthetic-site','contact','https://api.trial.ezyvet.com')$$,'Active admin claims first page');
select throws_ok($$select public.claim_ezyvet_import('e2000000-0000-4000-8000-000000000002','e1000000-0000-4000-8000-000000000001','synthetic-site','contact','https://api.trial.ezyvet.com')$$,'55P03','Import busy or cooling down','Concurrent run for same source resource is blocked');
select throws_ok($$select public.stage_ezyvet_import_page('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',gen_random_uuid(),1,false,'[]')$$,'40001','Import lease or cursor changed','Wrong lease cannot advance');
select throws_ok($$select public.stage_ezyvet_import_page('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',(select lease_id from public.ezyvet_import_runs where id='e2000000-0000-4000-8000-000000000001'),2,false,'[]')$$,'40001','Import lease or cursor changed','Skipped cursor rejected');
select throws_ok($$select public.stage_ezyvet_import_page('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',(select lease_id from public.ezyvet_import_runs where id='e2000000-0000-4000-8000-000000000001'),1,false,'[]')$$,'23514','Empty intermediate page','Empty incomplete page rejected');
select throws_ok($$select public.stage_ezyvet_import_page('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',(select lease_id from public.ezyvet_import_runs where id='e2000000-0000-4000-8000-000000000001'),1,true,'[{"external_id":"1","payload":{"id":1}},{"external_id":"1","payload":{"id":1}}]')$$,'23514','Duplicate external IDs','Duplicate upstream IDs rejected transactionally');
select lives_ok($$select public.stage_ezyvet_import_page('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',(select lease_id from public.ezyvet_import_runs where id='e2000000-0000-4000-8000-000000000001'),1,false,'[{"external_id":"1","payload":{"id":1,"first_name":"Synthetic"}}]')$$,'First page staged');
select is((select next_page from public.ezyvet_import_runs where id='e2000000-0000-4000-8000-000000000001'),2,'Cursor advances atomically');
select lives_ok($$select public.stage_ezyvet_import_page('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',null,1,false,'[{"external_id":"1","payload":{"id":1,"first_name":"Different response"}}]')$$,'Committed page replay is no-op');
select is((select payload->>'first_name' from public.ezyvet_import_snapshots where source_site_uid='synthetic-site'),'Synthetic','Committed snapshot stays immutable');
reset role;
update public.ezyvet_import_runs set retry_after=null where id='e2000000-0000-4000-8000-000000000001';
set local role service_role;
select lives_ok($$select public.claim_ezyvet_import('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','synthetic-site','contact','https://api.trial.ezyvet.com')$$,'Second page claimed');
select lives_ok($$select public.fail_ezyvet_import_page('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',(select lease_id from public.ezyvet_import_runs where id='e2000000-0000-4000-8000-000000000001'),'RATE_LIMITED',60)$$,'Rate limit saved without moving cursor');
select is((select next_page from public.ezyvet_import_runs where id='e2000000-0000-4000-8000-000000000001'),2,'Failure retains cursor');
select throws_ok($$select public.claim_ezyvet_import('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','synthetic-site','contact','https://api.trial.ezyvet.com')$$,'55P03','Import busy or cooling down','Provider cooldown enforced');
reset role;
update public.ezyvet_import_runs set retry_after=null where id='e2000000-0000-4000-8000-000000000001';
set local role service_role;
select public.claim_ezyvet_import('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','synthetic-site','contact','https://api.trial.ezyvet.com');
select lives_ok($$select public.stage_ezyvet_import_page('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',(select lease_id from public.ezyvet_import_runs where id='e2000000-0000-4000-8000-000000000001'),2,true,'[{"external_id":"1","payload":{"id":1,"first_name":"Synthetic"}}]')$$,'Identical upstream snapshot deduped on next page');
select is((select count(*) from public.ezyvet_import_snapshots),1::bigint,'Identical source ID and payload deduplicates');
select is((select count(*) from public.ezyvet_import_page_items),2::bigint,'Both page observations retained');
select is((select status from public.ezyvet_import_runs where id='e2000000-0000-4000-8000-000000000001'),'review_ready','Complete import awaits review');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.ezyvet_import_snapshots),0::bigint,'Regular staff cannot read staged private source records');
select throws_ok($$select public.review_ezyvet_snapshot(gen_random_uuid(),'ignored',null,null,'Not our record')$$,'42501','Active administrator required','Regular staff cannot review imports');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select count(*) from public.ezyvet_import_snapshots),1::bigint,'Admin reads staged source records');
select lives_ok($$select public.review_ezyvet_snapshot((select id from public.ezyvet_import_snapshots limit 1),'unmatched',null,null,'Needs matching review')$$,'Admin records review without modifying source');
select lives_ok($$select public.review_ezyvet_snapshot((select id from public.ezyvet_import_snapshots limit 1),'ignored',null,null,'Reviewed duplicate source')$$,'Changed decision appends history');
select is((select count(*) from public.ezyvet_import_reviews),2::bigint,'Both reviews retained');
select throws_ok($$select public.review_ezyvet_snapshot((select id from public.ezyvet_import_snapshots limit 1),'proposed_match',null,gen_random_uuid(),'Invalid target')$$,'23514','Match target does not fit imported resource','Contact cannot match to patient');
reset role;
select is((select count(*) from public.clients),(select clients from original_counts),'Import leaves client records unchanged');
select is((select count(*) from public.pets),(select pets from original_counts),'No absent-patient deletion or imported patient creation');
select is((select count(*) from public.clinical_encounters),(select encounters from original_counts),'Import leaves clinical charts unchanged');
select * from finish();
rollback;
